import FreeCAD
import Part
import Sketcher

# Open the precondition file
doc = FreeCAD.open("/home/user/Precondition_Unnamed.FCStd")

sketches = [obj for obj in doc.Objects if 'Sketch' in obj.TypeId]

for sketch in sketches:
    print(f"\n=== Analyzing constraints for each geometry ===")

    # Map which constraints affect which geometry
    geom_constraints = {0: [], 1: [], 2: [], 3: [], 4: [], 5: []}

    for i, constraint in enumerate(sketch.Constraints):
        first = constraint.First
        second = constraint.Second

        if first >= 0 and first < 6:
            geom_constraints[first].append((i, constraint.Type))
        if second >= 0 and second < 6:
            geom_constraints[second].append((i, constraint.Type))

    for geom_idx, constraints in geom_constraints.items():
        print(f"Geometry {geom_idx}: {constraints}")

    print("\n=== Detailed constraint analysis ===")
    for i, constraint in enumerate(sketch.Constraints):
        print(f"C{i}: Type={constraint.Type}, First={constraint.First}, Second={constraint.Second}, Value={constraint.Value}")
EOF
